Thực hiện phép tính $ \dfrac{4 x + 2}{3 x + 2}+ \left[ \dfrac{3}{5 x + 4}-\left( \dfrac{1 - x}{3 x + 2}+\dfrac{3}{5 x + 4} \right) \right] $ 
\choice
{ $\dfrac{5 x + 2}{3 x + 2}$  }
   { $\dfrac{5 x + 3}{3 x + 2}$  }
     { \True $\dfrac{5 x + 1}{3 x + 2}$  }
    { $\dfrac{5 x}{3 x + 2}$  }
\loigiai{
$ \dfrac{4 x + 2}{3 x + 2}+ \left[ \dfrac{3}{5 x + 4}-\left( \dfrac{1 - x}{3 x + 2}+\dfrac{3}{5 x + 4} \right) \right]=\dfrac{5 x + 1}{3 x + 2}$
}\end{ex}

\begin{ex}%[8D6H2]
Thực hiện phép tính $ \dfrac{- x - 5}{x - 4}+ \left[ \dfrac{x + 4}{6 x + 3}-\left( \dfrac{x - 5}{x - 4}+\dfrac{x + 4}{6 x + 3} \right) \right] $ 
\choice
{ $\dfrac{- 2 x - 1}{x - 4}$  }
   { \True $- \dfrac{2 x}{x - 4}$  }
     { $\dfrac{2 - 2 x}{x - 4}$  }
    { $\dfrac{1 - 2 x}{x - 4}$  }
\loigiai{
$ \dfrac{- x - 5}{x - 4}+ \left[ \dfrac{x + 4}{6 x + 3}-\left( \dfrac{x - 5}{x - 4}+\dfrac{x + 4}{6 x + 3} \right) \right]=- \dfrac{2 x}{x - 4}$
}\end{ex}

\begin{ex}%[8D6H2]
Thực hiện phép tính $ \dfrac{x - 3}{2 x^{2} - 1}- \left( \dfrac{x - 2}{x + 3}+ \dfrac{2 - 5 x}{3 x - 3} \right)+\left[  \dfrac{x - 2}{x + 3}- \left( \dfrac{- 3 x - 5}{2 x^{2} - 1}-\dfrac{2 - 5 x}{3 x - 3}      \right) \right] $ 
\choice
{ $\dfrac{4 x + 1}{2 x^{2} - 1}$  }
   { $\dfrac{4 x + 4}{2 x^{2} - 1}$  }
     { \True $\dfrac{4 x + 2}{2 x^{2} - 1}$  }
    { $\dfrac{4 x + 3}{2 x^{2} - 1}$  }
\loigiai{
Phân tích tử và mẫu thành nhân tử (hoặc khai triển hằng đẳng thức, quy đồng/nghịch đảo phép chia) rồi rút gọn: $\dfrac{x - 3}{2 x^{2} - 1}- \left( \dfrac{x - 2}{x + 3}+ \dfrac{2 - 5 x}{3 x - 3} \right)+\left[  \dfrac{x - 2}{x + 3}- \left( \dfrac{- 3 x - 5}{2 x^{2} - 1}-\dfrac{2 - 5 x}{3 x - 3}      \right) \right] = \frac{2 \left(2 x + 1\right)}{2 x^{2} - 1}$.
}\end{ex}
